def solve():
    solutions = []
    for a in range(1, 10):
        # c < 2012/a^2
        max_c = 2012 // (a**2) + 100
        for b in range(a, max_c + 1):
            for c in range(b, max_c + 1):
                lhs = a**3 * (b**3 + c**3)
                rhs = 2012 * (a * b * c + 2)
                if lhs == rhs:
                    solutions.append((a, b, c))
    return solutions

print(solve())

